{
  "summary": "Implement the matching logic in matcher.py to detect missing_left, missing_right, amount_mismatch, and duplicate_left discrepancies, and implement render_summary in report.py to output counts of each discrepancy kind.",
  "files": [
    {
      "path": "reconcile/matcher.py",
      "content": "from __future__ import annotations

from collections import Counter
from typing import Iterable

from .models import Discrepancy, Row


def find_discrepancies(left_rows: Iterable[Row], right_rows: Iterable[Row]) -> list[Discrepancy]:
    left_list = list(left_rows)
    right_list = list(right_rows)

    discrepancies: list[Discrepancy] = []

    # Build key -> list of rows for left and right
    def key(row: Row) -> tuple[str, str]:
        return (row.merchant_order_id, row.provider_txn_id)

    left_by_key: dict[tuple[str, str], list[Row]] = {}
    for row in left_list:
        k = key(row)
        left_by_key.setdefault(k, []).append(row)

    right_by_key: dict[tuple[str, str], list[Row]] = {}
    for row in right_list:
        k = key(row)
        right_by_key.setdefault(k, []).append(row)

    all_keys = set(left_by_key.keys()) | set(right_by_key.keys())

    for k in all_keys:
        left_rows_for_k = left_by_key.get(k, [])
        right_rows_for_k = right_by_key.get(k, [])

        # Check for duplicates on left
        if len(left_rows_for_k) > 1:
            discrepancies.append(
                Discrepancy(
                    kind="duplicate_left",
                    merchant_order_id=k[0],
                    provider_txn_id=k[1],
                    detail=f"Found {len(left_rows_for_k)} rows on left",
                )
            )

        # Check for duplicates on right
        if len(right_rows_for_k) > 1:
            discrepancies.append(
                Discrepancy(
                    kind="duplicate_right",
                    merchant_order_id=k[0],
                    provider_txn_id=k[1],
                    detail=f"Found {len(right_rows_for_k)} rows on right",
                )
            )

        # Missing on left
        if not left_rows_for_k and right_rows_for_k:
            row = right_rows_for_k[0]
            discrepancies.append(
                Discrepancy(
                    kind="missing_left",
                    merchant_order_id=row.merchant_order_id,
                    provider_txn_id=row.provider_txn_id,
                    detail="Present on right but not on left",
                )
            )

        # Missing on right
        if left_rows_for_k and not right_rows_for_k:
            row = left_rows_for_k[0]
            discrepancies.append(
                Discrepancy(
                    kind="missing_right",
                    merchant_order_id=row.merchant_order_id,
                    provider_txn_id=row.provider_txn_id,
                    detail="Present on left but not on right",
                )
            )

        # Amount mismatch (only if both sides have at least one row)
        if left_rows_for_k and right_rows_for_k:
            left_amounts = {r.amount_cents for r in left_rows_for_k}
            right_amounts = {r.amount_cents for r in right_rows_for_k}
            if left_amounts != right_amounts:
                # Report mismatch using first row from each side
                left_row = left_rows_for_k[0]
                right_row = right_rows_for_k[0]
                discrepancies.append(
                    Discrepancy(
                        kind="amount_mismatch",
                        merchant_order_id=left_row.merchant_order_id,
                        provider_txn_id=left_row.provider_txn_id,
                        detail=f"Left amount {left_row.amount_cents} != Right amount {right_row.amount_cents}",
                    )
                )

    return discrepancies
